const crypto = require("crypto");
const candidates = [
  "quarterly-report-2026",
  "quarterly-report_2026",
  "quarterly_report_2026",
  "quarterly-report_-2026",
  "Quarterly-Report_2026",
  "quarterly report_2026",
  "quarterly-report-_2026",
];
for (const c of candidates) {
  const d = crypto.createHash("sha256").update(c, "utf8").digest("hex");
  console.log(d, JSON.stringify(c));
}
'
